components.css:
.ds-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1px solid transparent;
  font-family: inherit;
  font-weight: 600;
  line-height: 1;
  letter-spacing: 0;
  white-space: nowrap;

  text-decoration: none;
  cursor: pointer;
  transition:
    background-color 0.15s ease,
    border-color 0.15s ease,
    color 0.15s ease,
    opacity 0.15s ease;
}
.ds-button:focus {
  outline: none;
}
.ds-button:focus-visible {
  box-shadow: 0 0 0 2px var(--accent-primary);
}
.ds-button:disabled {
  background: var(--bg-secondary);
  border-color: var(--border-default);
  color: var(--text-muted);
  cursor: not-allowed;
  opacity: 0.68;
}
.ds-control--rounded {
  border-radius: var(--radius-lg);
}
.ds-control--sm {
  height: 28px;
  padding: 0 10px;
  font-size: 0.75rem;
}
.ds-button--primary {
  background: var(--accent-primary);
  border-color: var(--accent-primary);
  color: var(--text-inverse);
}
.ds-button--primary:hover:not(:disabled) {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}
.ds-button--secondary {
  background: var(--bg-elevated);
  border-color: var(--border-default);
  color: var(--text-primary);
}
.ds-button--secondary:hover:not(:disabled) {
  background: var(--bg-surface);
}
.ds-button--secondary[data-active] {
  background: color-mix(in srgb, var(--accent-primary) 17%, var(--bg-elevated));
  border-color: var(--accent-primary);
}
.ds-button--danger {
  background: var(--status-danger);
  border-color: var(--status-danger);
  color: var(--text-inverse);
}
.ds-button { font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
@media (pointer: coarse) { .ds-control--sm { min-height: var(--touch-target); } }

